import { useActiveOrganization } from '@/hooks/use-active-organization';
import {
  isCurrentPageIdentity,
  refreshActiveTabIdentity,
  useActiveTab,
} from '@/hooks/use-active-tab';
import type { ExtractionSource } from '@/hooks/use-extraction';
import { useUserTables } from '@/hooks/use-user-tables';
import { isDbFailureError } from '@/lib/supabase/db-failure';
import { type ExtractionPatternField, type PatternKind, savePattern } from '@/lib/supabase/queries';
import {
  buildFieldNameMap,
  inferSchemaFromRows,
  tableColumnKeys,
  tableOrganization,
  unionRowKeys,
} from '@/lib/supabase/user-tables';
import { OrganizationContextError, requireOrganizationContext } from '@ai-matrx/agents/matrx';
import {
  Button,
  BasicInput as Input,
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@ai-matrx/design-system';
import { CheckCircle2, Loader2, Save, TriangleAlert } from 'lucide-react';
import { useMemo, useRef, useState } from 'react';

const NEW_TABLE = '__new__';
const NO_TABLE = '__none__';

interface SaveAsPatternProps {
  defaultName?: string;
  kind: PatternKind;
  config: unknown;
  /** Only used when kind === 'manual_css'. */
  fields?: ExtractionPatternField[];
  /** Only used when kind === 'manual_css'. */
  list_root_selector?: string | null;
  /** Preview rows that get appended to the target user_table on save. */
  rows: Record<string, unknown>[];
  /**
   * Where the rows were actually extracted (captured at extraction time).
   * The pattern is stored under THIS host/route — not whatever tab the user
   * happens to be on at save time (audit P0-2). When omitted, falls back to
   * the live tab.
   */
  source?: ExtractionSource | null;
  disabled?: boolean;
  onSaved?: () => void;
}

export function SaveAsPattern({
  defaultName = '',
  kind,
  config,
  fields,
  list_root_selector,
  rows,
  source,
  disabled,
  onSaved,
}: SaveAsPatternProps) {
  const tab = useActiveTab();
  // This component mounts with the rows it offers to save. A navigation can
  // precede React's next render, so the click also checks the shared snapshot.
  const resultPageKey = useRef(tab.pageKey);
  const resultIsCurrent = isCurrentPageIdentity(resultPageKey.current);
  const [open, setOpen] = useState(false);
  const [name, setName] = useState(defaultName);
  const [target, setTarget] = useState<string>(NO_TABLE);
  const [newTableName, setNewTableName] = useState('');
  const [saving, setSaving] = useState(false);
  const [savedSummary, setSavedSummary] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  const { active: activeOrganization, organizations } = useActiveOrganization();
  // The picker lists tables across ALL of the person's organizations (active-org law
  // 2026-09-30); the active organization is only where a NEW table is created.
  const { tables, createTable, appendRows } = useUserTables();
  const orgName = (id: string | null) => organizations.find((o) => o.id === id)?.name ?? null;

  // Union across ALL rows — the preview table shows every column, so the
  // created table must too (single-row inference silently dropped columns
  // that only appear in later rows).
  const inferredFields = useMemo(() => (rows.length ? inferSchemaFromRows(rows) : []), [rows]);

  const liveHost = useMemo(() => {
    try {
      return tab.url ? new URL(tab.url).host : '';
    } catch {
      return '';
    }
  }, [tab.url]);

  // Pattern identity comes from where the rows were EXTRACTED, not where the
  // user is now. The mismatch warning covers flows whose rows can outlive a
  // navigation (network capture, AI extract).
  const host = source?.host ?? liveHost;
  const routePattern = source?.pathname ?? (tab.url ? safePathname(tab.url) : null);
  const hostMismatch = Boolean(source?.host && liveHost && source.host !== liveHost);

  const handleSave = async () => {
    if (!host) return;
    if (!isCurrentPageIdentity(resultPageKey.current)) {
      setErr('This result belongs to a previous page. Capture the current page, then save it.');
      return;
    }

    // Capture the operation organization at the initiating click. A NEW table is created in the
    // active organization; an EXISTING table is written in ITS OWN organization. A later
    // Settings change must not redirect this in-flight dataset create.
    const chosenTable =
      target !== NEW_TABLE && target !== NO_TABLE
        ? tables?.find((t) => t.id === target)
        : undefined;
    let operationOrganizationId: string;
    try {
      operationOrganizationId = requireOrganizationContext(
        chosenTable?.organization_id ?? activeOrganization?.id,
      );
    } catch (error) {
      setErr(error instanceof Error ? error.message : String(error));
      return;
    }
    setSaving(true);
    setErr(null);
    setSavedSummary(null);

    // Validate regex transforms NOW — a bad pattern saved today is a silent
    // null column on every future run (audit G3).
    const badRegex = invalidRegexInConfig(kind, config);
    if (badRegex) {
      setErr(`Field "${badRegex.field}" has an invalid regex: ${badRegex.error}`);
      setSaving(false);
      return;
    }

    try {
      let targetTableId: string | null = null;

      if (!isCurrentPageIdentity(resultPageKey.current))
        throw new Error('The page changed before Save. Capture it again.');
      if (target === NEW_TABLE) {
        // Throws on refusal (the user already saw the reason as a notice);
        // the catch at the bottom of this function renders the same sentence
        // in the popover.
        const created = await createTable({
          table_name: newTableName || name || `${host} extraction`,
          description: `Auto-created from matrx-extend ${kind} pattern.`,
          organization_id: operationOrganizationId,
          fields: inferredFields,
        });
        targetTableId = created.id;
      } else if (target !== NO_TABLE) {
        targetTableId = target;
        // Load the persisted parent before any linked write. The selected
        // value is only a UI choice; its organization is authoritative here.
        // From whichever store holds it (lane INTEG-CLIENTS): a moved table is a record-store Table.
        const existingOrganizationId = await tableOrganization(
          targetTableId,
          operationOrganizationId,
        );
        if (!existingOrganizationId) {
          throw new OrganizationContextError(
            'organization_context_required',
            'This dataset has no organization. Choose a different dataset or create a new one.',
          );
        }
        if (requireOrganizationContext(existingOrganizationId) !== operationOrganizationId) {
          throw new OrganizationContextError(
            'organization_context_mismatch',
            'The selected dataset belongs to a different organization than the one this save runs in. Pick it again.',
          );
        }
      }

      if (!isCurrentPageIdentity(resultPageKey.current))
        throw new Error('The page changed before Save. Capture it again.');
      const saved = await savePattern({
        // DD-131: the person clicked "Save as pattern" in Showcase — no actor header.
        authored_by: 'person',
        organization_id: operationOrganizationId,
        name: name || `${host} ${kind}`,
        domain: host,
        route_pattern: routePattern,
        list_root_selector: list_root_selector ?? null,
        fields: fields ?? [],
        kind,
        config,
        target_user_table_id: targetTableId,
      });

      if (!saved) {
        setErr('Failed to save pattern.');
        setSaving(false);
        return;
      }

      if (targetTableId && rows.length > 0) {
        // Appending to an EXISTING table: the RPC silently drops keys with no
        // matching column. Diff against the live schema so dropped columns
        // are reported, not invisible.
        let unmatchedNote = '';
        if (target !== NEW_TABLE) {
          const columnKeys = await tableColumnKeys(targetTableId, operationOrganizationId);
          if (columnKeys.length > 0) {
            const declared = new Set(columnKeys);
            const mapped = buildFieldNameMap(unionRowKeys(rows));
            const unmatched = [...new Set(mapped.values())].filter((f) => !declared.has(f));
            if (unmatched.length > 0) {
              unmatchedNote = ` · ${unmatched.length} column${unmatched.length === 1 ? '' : 's'} had no match (${unmatched.slice(0, 3).join(', ')}${unmatched.length > 3 ? ', …' : ''}) and was dropped`;
            }
          }
        }

        let result: { inserted: number };
        try {
          if (!isCurrentPageIdentity(resultPageKey.current))
            throw new Error('The page changed before rows could be saved. Capture it again.');
          result = await appendRows(targetTableId, operationOrganizationId, rows);
        } catch (appendErr) {
          // The pattern row IS saved — but the rows are not. Saying
          // "0 rows appended" here would be a success banner over data loss.
          const why = isDbFailureError(appendErr) ? ` ${appendErr.userMessage}` : '';
          setErr(
            `Pattern saved, but appending ${rows.length} row${rows.length === 1 ? '' : 's'} to the table failed.${why} Run the pattern again and re-save, or append from the Patterns tab.`,
          );
          onSaved?.();
          setSaving(false);
          return;
        }
        const appendedCount = result.inserted;
        setSavedSummary(
          `Pattern saved · ${appendedCount} row${appendedCount === 1 ? '' : 's'} appended${unmatchedNote}`,
        );
      } else {
        setSavedSummary('Pattern saved');
      }
      onSaved?.();
      setTimeout(() => setOpen(false), 1200);
    } catch (e) {
      setErr(isDbFailureError(e) ? e.userMessage : e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  };

  const canSave = host && resultIsCurrent && !saving && (rows.length > 0 || kind === 'manual_css');

  return (
    <>
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant="secondary"
            disabled={disabled || !host || !resultIsCurrent}
            className="rounded-full"
            title={host ? 'Save as pattern' : 'No active page'}
          >
            <Save className="size-3.5" />
            Save pattern
          </Button>
        </PopoverTrigger>
        {/* `align="end"` is explicit since the design-system PopoverContent
          defaults to "center" (the deleted local fork defaulted to "end"). */}
        <PopoverContent align="end" className="w-80 space-y-3 p-3">
          <div className="space-y-1">
            <div className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
              Save pattern
            </div>
            <div className="text-xs text-muted-foreground">
              Save under {host}. Reopen and run it from Patterns.
              {kind === 'network_capture' &&
                ' Network reruns reload the open page and listen for a matching request.'}
            </div>
          </div>

          {hostMismatch && (
            <div className="flex items-start gap-1.5 rounded-lg bg-amber-500/10 px-2 py-1.5 text-[11px] text-amber-700 dark:text-amber-300">
              <TriangleAlert className="mt-px size-3 shrink-0" />
              <span>
                These rows were extracted on <span className="font-medium">{source?.host}</span>,
                but you're now on <span className="font-medium">{liveHost}</span>. The pattern saves
                under {source?.host}.
              </span>
            </div>
          )}

          <Input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder={`${host} ${kind}`}
            className="h-8 rounded-full text-xs"
          />

          <div className="space-y-1">
            <div className="text-[11px] font-medium text-muted-foreground">Target user table</div>
            <select
              value={target}
              onChange={(e) => setTarget(e.target.value)}
              className="h-8 w-full rounded-full bg-secondary/40 px-3 text-xs outline-none focus-visible:ring-1"
            >
              <option value={NO_TABLE}>(don't append rows now)</option>
              <option value={NEW_TABLE}>+ Create new from these fields…</option>
              {tables?.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.table_name}
                  {orgName(t.organization_id) ? ` · ${orgName(t.organization_id)}` : ''}
                </option>
              ))}
            </select>
          </div>

          {target === NEW_TABLE && (
            <div className="space-y-2 rounded-xl bg-secondary/40 p-2">
              <Input
                value={newTableName}
                onChange={(e) => setNewTableName(e.target.value)}
                placeholder="New table name…"
                className="h-7 rounded-full bg-background text-xs"
              />
              <div className="space-y-1">
                <div className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
                  Inferred schema
                </div>
                {inferredFields.length === 0 ? (
                  <div className="text-[11px] text-muted-foreground">
                    Run extraction first to infer fields.
                  </div>
                ) : (
                  <div className="max-h-32 space-y-0.5 overflow-y-auto">
                    {inferredFields.map((f) => (
                      <div
                        key={f.field_name}
                        className="flex items-center justify-between gap-2 text-[11px]"
                      >
                        <span className="min-w-0 truncate">
                          <span className="truncate font-mono">{f.field_name}</span>
                          {f.display_name !== f.field_name && (
                            <span className="ml-1 truncate text-muted-foreground">
                              ({f.display_name})
                            </span>
                          )}
                        </span>
                        <span className="shrink-0 text-muted-foreground">{f.data_type}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}

          {err && (
            <div className="rounded-lg bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
              {err}
            </div>
          )}

          {savedSummary && (
            <div className="flex items-center gap-1.5 rounded-lg bg-emerald-500/10 px-2 py-1 text-[11px] text-emerald-700 dark:text-emerald-300">
              <CheckCircle2 className="size-3" />
              {savedSummary}
            </div>
          )}

          <div className="flex justify-end gap-2">
            <Button size="sm" variant="ghost" onClick={() => setOpen(false)} className="h-7">
              Cancel
            </Button>
            <Button size="sm" onClick={() => void handleSave()} disabled={!canSave} className="h-7">
              {saving ? <Loader2 className="size-3 animate-spin" /> : <Save className="size-3" />}
              Save
            </Button>
          </div>
        </PopoverContent>
      </Popover>
      {!resultIsCurrent && (
        <span className="text-xs text-muted-foreground">
          {tab.identityError ?? 'Checking the current page…'}{' '}
          <button
            type="button"
            className="underline"
            onClick={() => void refreshActiveTabIdentity()}
          >
            Retry
          </button>
        </span>
      )}
    </>
  );
}

/** list_pattern configs carry per-field regex transforms — compile-check them. */
function invalidRegexInConfig(
  kind: PatternKind,
  config: unknown,
): { field: string; error: string } | null {
  if (kind !== 'list_pattern' || !config || typeof config !== 'object') return null;
  const fieldPaths = (config as { field_paths?: unknown }).field_paths;
  if (!Array.isArray(fieldPaths)) return null;
  for (const f of fieldPaths) {
    const field = f as { name?: string; transform?: { kind?: string; expr?: string } };
    if (field.transform?.kind === 'regex' && field.transform.expr) {
      try {
        new RegExp(field.transform.expr);
      } catch (e) {
        return {
          field: field.name ?? '(unnamed)',
          error: e instanceof Error ? e.message : String(e),
        };
      }
    }
  }
  return null;
}

function safePathname(url: string): string | null {
  try {
    return new URL(url).pathname;
  } catch {
    return null;
  }
}
