import {
  getActiveTabIdentitySnapshot,
  isCurrentPageIdentity,
  useActiveTab,
} from '@/hooks/use-active-tab';
import { urlMatchesPattern } from '@/lib/data-pattern/matcher';
import { NetworkNoMatchError, runSavedPattern } from '@/lib/data-pattern/run-interactive';
import { classifySavedRun } from '@/lib/data-pattern/saved-run-outcome';
import { confirmDestructive } from '@/lib/destructive/confirm';
import {
  type ExtractionPattern,
  bumpPatternRun,
  deletePattern,
  fetchPatternsForDomain,
  renamePattern,
} from '@/lib/supabase/queries';
import { cn } from '@/lib/utils';
import { Button, BasicInput as Input } from '@ai-matrx/design-system';
// THE package formatters (`@ai-matrx/kit/format`, duplication census H1
// 2026-09-07): the fleet had ~35 duration, ~18 relative-time and ~20 byte-size
// twins with no correct owner until kit became one.
import { formatRelativeTime } from '@ai-matrx/kit/format';
import {
  Check,
  CheckCircle2,
  Loader2,
  Pencil,
  PlayCircle,
  RefreshCw,
  Trash2,
  X,
  XCircle,
} from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { ResultPreview } from '../components/ResultPreview';

const KIND_LABELS: Record<string, string> = {
  manual_css: 'Manual',
  json_ld: 'JSON-LD',
  og_meta: 'Snapshot',
  auto_table: 'Table',
  next_data: 'Framework',
  ai_extract: 'AI',
  list_pattern: 'List',
  microdata: 'Microdata',
  network_capture: 'Network',
};

export function PatternsTab({ active = true }: { active?: boolean }) {
  const tab = useActiveTab();
  const [patternSnapshot, setPatternSnapshot] = useState<{
    pageKey: string;
    patterns: ExtractionPattern[];
  } | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [runError, setRunError] = useState<string | null>(null);
  const [runningId, setRunningId] = useState<string | null>(null);
  const [runNote, setRunNote] = useState<string | null>(null);
  const [rows, setRows] = useState<Record<string, unknown>[] | null>(null);
  const [resultSource, setResultSource] = useState<{
    url: string | null;
    title: string | null;
  } | null>(null);
  const [activeName, setActiveName] = useState<string | null>(null);
  const [runInfo, setRunInfo] = useState<string | null>(null);
  const [resultPageKey, setResultPageKey] = useState<string | null>(null);
  const pageKey = tab.pageKey ?? '';
  const patterns = patternSnapshot?.pageKey === pageKey ? patternSnapshot.patterns : null;
  const visibleRows = tab.pageKey && resultPageKey === pageKey ? rows : null;
  const visibleRunInfo = resultPageKey === pageKey ? runInfo : null;
  const visibleRunError = resultPageKey === pageKey ? runError : null;
  const currentPageKey = useRef(pageKey);
  const previousPageKey = useRef(pageKey);
  const loadSeq = useRef(0);
  const runSeq = useRef(0);
  const replayOwner = useRef<{
    seq: number;
    tabId: number;
    url: string;
    documentId: string | null;
  } | null>(null);
  currentPageKey.current = pageKey;

  const host = (() => {
    try {
      return tab.url ? new URL(tab.url).host : '';
    } catch {
      return '';
    }
  })();

  const refresh = useCallback(async () => {
    if (!host) return;
    const seq = ++loadSeq.current;
    setLoading(true);
    setLoadError(null);
    try {
      const found = await fetchPatternsForDomain(host);
      if (seq === loadSeq.current && currentPageKey.current === pageKey) {
        setPatternSnapshot({ pageKey, patterns: found });
      }
    } catch (err) {
      if (seq === loadSeq.current && currentPageKey.current === pageKey) {
        setLoadError(err instanceof Error ? err.message : String(err));
      }
    } finally {
      if (seq === loadSeq.current && currentPageKey.current === pageKey) setLoading(false);
    }
  }, [host, pageKey]);
  const refreshCurrent = useRef(refresh);
  refreshCurrent.current = refresh;

  useEffect(() => {
    if (previousPageKey.current === pageKey) return;
    previousPageKey.current = pageKey;
    loadSeq.current += 1;
    const owner = replayOwner.current;
    const replayStillOnRoute =
      owner?.seq === runSeq.current && tab.id === owner.tabId && tab.url === owner.url;
    if (!replayStillOnRoute) {
      runSeq.current += 1;
      replayOwner.current = null;
    }
    setPatternSnapshot(null);
    setLoading(false);
    setLoadError(null);
    if (!replayStillOnRoute) {
      setRunningId(null);
      setRunNote(null);
    }
    setRunError(null);
    setRunInfo(null);
    setRows(null);
    setResultSource(null);
    setActiveName(null);
    setResultPageKey(null);
  }, [pageKey, tab.id, tab.url]);

  useEffect(
    () => () => {
      loadSeq.current += 1;
      runSeq.current += 1;
      replayOwner.current = null;
    },
    [],
  );

  // Re-fetch whenever this tab becomes the visible one — picks up patterns
  // saved from sibling tabs without a manual refresh.
  useEffect(() => {
    if (active) void refresh();
  }, [active, refresh]);

  const handleRun = async (p: ExtractionPattern) => {
    if (!tab.id || !tab.documentId || !tab.pageKey) return;
    const runPageKey = pageKey;
    const seq = ++runSeq.current;
    replayOwner.current =
      p.kind === 'network_capture' && tab.url
        ? { seq, tabId: tab.id, url: tab.url, documentId: null }
        : null;
    const isCurrent = () =>
      seq === runSeq.current &&
      (replayOwner.current?.seq === seq
        ? (() => {
            const owner = replayOwner.current;
            const current = getActiveTabIdentitySnapshot();
            return (
              current.id === owner.tabId &&
              current.url === owner.url &&
              current.identityStatus === 'ready' &&
              Boolean(current.pageKey) &&
              (!owner.documentId || current.documentId === owner.documentId)
            );
          })()
        : currentPageKey.current === runPageKey && isCurrentPageIdentity(runPageKey));
    const onSavedRoute = urlMatchesPattern(tab.url ?? '', p);
    const sourceAtRun = { url: tab.url, title: tab.title };
    setRunningId(p.id);
    setResultPageKey(runPageKey);
    setActiveName(p.name);
    setRows(null);
    setResultSource(null);
    setRunError(null);
    setRunNote(null);
    setRunInfo(null);
    try {
      // 'user': handleRun is the Run control on a pattern row.
      const data = await runSavedPattern(p, tab.id, {
        onProgress: (note) => {
          if (isCurrent()) setRunNote(note);
        },
        onReplayDocument: (documentId) => {
          if (replayOwner.current?.seq === seq) replayOwner.current.documentId = documentId;
        },
        initiation: 'user',
        documentId: tab.documentId,
      });
      if (!isCurrent()) return;
      if (replayOwner.current?.seq === seq)
        setResultPageKey(getActiveTabIdentitySnapshot().pageKey);
      setActiveName(p.name);
      setRows(data);
      setResultSource(sourceAtRun);
      const outcome = classifySavedRun(p, tab.url ?? '', data);
      setRunInfo(outcome.message);
      if (outcome.kind === 'matched') {
        const updateError = await bumpPatternRun(p.id, 'ok', data.length);
        if (isCurrent() && updateError) {
          setRunError(
            `Rows were extracted, but the saved run history could not be updated: ${updateError}`,
          );
        }
      }
    } catch (err) {
      if (!isCurrent()) return;
      if (replayOwner.current?.seq === seq)
        setResultPageKey(getActiveTabIdentitySnapshot().pageKey);
      if (err instanceof NetworkNoMatchError) {
        // Circumstantial — the page may just not have fired that API on
        // reload. Guidance only; don't mark the pattern broken.
        setRunError(err.message);
      } else {
        const failureMessage = `"${p.name}" failed: ${err instanceof Error ? err.message : String(err)}`;
        setRunError(failureMessage);
        if (onSavedRoute) {
          const updateError = await bumpPatternRun(p.id, 'broken', 0);
          if (isCurrent() && updateError) {
            setRunError(`${failureMessage} Saved run history could not be updated: ${updateError}`);
          }
        }
      }
    } finally {
      if (isCurrent()) {
        setRunningId(null);
        setRunNote(null);
        replayOwner.current = null;
        void refreshCurrent.current();
      }
    }
  };

  return (
    <div className="h-full overflow-y-auto">
      <div className="space-y-3 px-3 pb-3">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <div className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
              Patterns
            </div>
            <div className="text-xs text-muted-foreground">
              All saved patterns for {host || 'this host'}, across every mode.
            </div>
          </div>
          <Button
            size="icon"
            variant="ghost"
            onClick={() => void refresh()}
            className="size-7"
            title="Refresh"
          >
            {loading ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <RefreshCw className="size-3.5" />
            )}
          </Button>
        </div>

        {loadError && (
          <div className="flex items-center justify-between gap-2 rounded-xl bg-destructive/10 px-3 py-2 text-xs text-destructive">
            <span className="min-w-0">{loadError}</span>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => void refresh()}
              className="h-6 shrink-0 rounded-full px-2 text-[11px]"
            >
              Retry
            </Button>
          </div>
        )}

        {visibleRunError && (
          <div className="rounded-xl bg-destructive/10 px-3 py-2 text-xs text-destructive">
            {visibleRunError}
          </div>
        )}

        {visibleRunInfo && (
          <div className="rounded-xl bg-secondary px-3 py-2 text-xs text-muted-foreground">
            {visibleRunInfo}
          </div>
        )}

        {!loadError && patterns && patterns.length === 0 && (
          <div className="grid place-items-center rounded-xl bg-secondary/40 px-4 py-8 text-center text-sm text-muted-foreground">
            No saved patterns for this host yet. Save one from any tab.
          </div>
        )}

        {patterns && patterns.length > 0 && (
          <div className="space-y-1.5">
            {patterns.map((p) => (
              <PatternRow
                key={p.id}
                pattern={p}
                running={runningId === p.id}
                runNote={runningId === p.id ? runNote : null}
                canRun={Boolean(tab.pageKey)}
                routeMatches={urlMatchesPattern(tab.url ?? '', p)}
                onRun={() => void handleRun(p)}
                onChanged={() => void refresh()}
              />
            ))}
          </div>
        )}

        {visibleRows && visibleRows.length > 0 && (
          <div className="space-y-1">
            <div className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
              Last run: {activeName ?? '—'}
            </div>
            <ResultPreview
              rows={visibleRows}
              source={resultSource}
              description={`rows extracted by saved pattern "${activeName ?? 'unknown'}"`}
            />
          </div>
        )}
      </div>
    </div>
  );
}

function PatternRow({
  pattern: p,
  running,
  runNote,
  canRun,
  routeMatches,
  onRun,
  onChanged,
}: {
  pattern: ExtractionPattern;
  running: boolean;
  runNote?: string | null;
  canRun: boolean;
  routeMatches: boolean;
  onRun: () => void;
  onChanged: () => void;
}) {
  const [editing, setEditing] = useState(false);
  const [draftName, setDraftName] = useState(p.name);
  const [rowError, setRowError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const commitRename = async () => {
    if (draftName.trim() === p.name) {
      setEditing(false);
      return;
    }
    setBusy(true);
    setRowError(null);
    const err = await renamePattern(p.id, draftName);
    setBusy(false);
    if (err) {
      setRowError(err);
      return;
    }
    setEditing(false);
    onChanged();
  };

  const handleDelete = async () => {
    setRowError(null);
    // Was a click-twice-within-3s arm/disarm. That stopped the click but
    // named nothing; the law wants the consequence said out loud, and the
    // guard wants the ONE primitive.
    await confirmDestructive({
      title: `Delete the pattern "${p.name}"?`,
      consequence:
        `The saved ${p.kind === 'ai_extract' ? 'AI extraction' : 'extraction'} pattern for ${p.domain} is deleted for good. ` +
        'Rows it already extracted into your tables are kept; the recipe that produced them is not. This cannot be undone.',
      confirmLabel: 'Delete pattern',
      run: async () => {
        setBusy(true);
        // DD-131: the person clicked Delete in the Patterns tab — no actor header.
        const ok = await deletePattern(p.id, 'person');
        setBusy(false);
        if (!ok) {
          setRowError('Delete failed. Check your connection and try again.');
          return;
        }
        onChanged();
      },
    });
  };

  return (
    <div className="group space-y-1.5 rounded-xl bg-secondary/40 px-3 py-2">
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0 flex-1">
          {editing ? (
            <div className="flex items-center gap-1">
              <Input
                value={draftName}
                onChange={(e) => setDraftName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') void commitRename();
                  if (e.key === 'Escape') {
                    setDraftName(p.name);
                    setEditing(false);
                    setRowError(null);
                  }
                }}
                autoFocus
                className="h-6 rounded-full bg-background px-2 text-xs"
              />
              <Button
                size="icon"
                variant="ghost"
                onClick={() => void commitRename()}
                disabled={busy}
                className="size-6 shrink-0"
                title="Save name"
              >
                {busy ? <Loader2 className="size-3 animate-spin" /> : <Check className="size-3" />}
              </Button>
              <Button
                size="icon"
                variant="ghost"
                onClick={() => {
                  setDraftName(p.name);
                  setEditing(false);
                  setRowError(null);
                }}
                className="size-6 shrink-0"
                title="Cancel"
              >
                <X className="size-3" />
              </Button>
            </div>
          ) : (
            <div className="flex items-center gap-1.5">
              <span className="truncate text-sm font-medium">{p.name}</span>
              <KindBadge kind={p.kind} />
              <StatusBadge status={p.last_status} />
            </div>
          )}
          <div className="text-[11px] text-muted-foreground">
            {p.fields.length > 0 &&
              `${p.fields.length} field${p.fields.length === 1 ? '' : 's'} · `}
            {p.last_run_at ? `last run ${formatRelativeTime(p.last_run_at)}` : 'never run'}
            {p.last_run_count != null && ` · ${p.last_run_count} rows`}
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-0.5">
          {!editing && (
            <>
              <Button
                size="icon"
                variant="ghost"
                onClick={() => {
                  setDraftName(p.name);
                  setEditing(true);
                }}
                className="size-7 opacity-0 transition-opacity group-hover:opacity-100"
                title="Rename"
              >
                <Pencil className="size-3.5" />
              </Button>
              <Button
                size="icon"
                variant="ghost"
                onClick={() => void handleDelete()}
                disabled={busy}
                className="size-7 opacity-0 transition-opacity group-hover:opacity-100"
                title="Delete pattern"
              >
                <Trash2 className="size-3.5" />
              </Button>
            </>
          )}
          <Button
            size="icon"
            variant="ghost"
            onClick={onRun}
            disabled={running || !canRun}
            title="Run pattern"
            className="size-7"
          >
            {running ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <PlayCircle className="size-3.5" />
            )}
          </Button>
        </div>
      </div>
      {!routeMatches && p.route_pattern && (
        <div className="text-[11px] text-amber-700 dark:text-amber-400">
          Saved for {p.route_pattern}; this page is outside that route. You can still Run and review
          the result.
        </div>
      )}
      {running && runNote && (
        <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
          <Loader2 className="size-3 animate-spin" />
          {runNote}
        </div>
      )}
      {rowError && <div className="text-[11px] text-destructive">{rowError}</div>}
    </div>
  );
}

function KindBadge({ kind }: { kind: ExtractionPattern['kind'] }) {
  return (
    <span className="rounded-full bg-secondary px-1.5 py-px text-[9px] font-medium uppercase tracking-wider text-muted-foreground">
      {KIND_LABELS[kind] ?? kind}
    </span>
  );
}

function StatusBadge({ status }: { status: ExtractionPattern['last_status'] }) {
  if (!status) return null;
  return (
    <span
      className={cn(
        'flex items-center gap-0.5 rounded-full px-1.5 py-px text-[9px] font-medium uppercase tracking-wider',
        status === 'ok' && 'bg-emerald-500/15 text-emerald-700 dark:text-emerald-400',
        status === 'broken' && 'bg-red-500/15 text-red-600 dark:text-red-400',
        status === 'never_run' && 'bg-secondary text-muted-foreground',
      )}
    >
      {status === 'ok' && <CheckCircle2 className="size-2.5" />}
      {status === 'broken' && <XCircle className="size-2.5" />}
      {status === 'ok' ? 'ok' : status === 'broken' ? 'broken' : 'idle'}
    </span>
  );
}
