import { CopyMenu } from '@/components/CopyMenu';
import { rowsToTsv, stringifyJson, wrapJsonForAgent } from '@/lib/clipboard/copy';
import { sanitizePageSourceUrl } from '@/lib/credentials/network-urls';
import { cn } from '@/lib/utils';
import { useChatStore } from '@/state/chat';
import { useSidepanelTabStore } from '@/state/sidepanel-tab';
import { Button } from '@ai-matrx/design-system';
import { Bot, Braces, Table2 } from 'lucide-react';
import { useMemo, useState } from 'react';

/** Rows included inline when handing results to the agent (context cost). */
const AGENT_HANDOFF_ROW_CAP = 50;

type View = 'table' | 'json';

interface ResultPreviewProps {
  rows: Record<string, unknown>[];
  emptyHint?: string;
  maxHeight?: number;
  /** Source URL/title for AI-wrapped copy. Optional. */
  source?: { url?: string | null; title?: string | null } | null;
  /** What the URL identifies for this result. */
  sourceKind?: 'page' | 'response';
  /** Mode/recipe label for AI-wrapped copy. Optional. */
  description?: string;
}

/**
 * Shared result preview used by every Showcase sub-tab. Toggles between a
 * table view (good for tabular extraction like Mode D, list pattern) and a
 * raw-JSON view (good for nested objects like JSON-LD or framework data).
 */
export function ResultPreview({
  rows,
  emptyHint,
  maxHeight = 320,
  source,
  sourceKind = 'page',
  description = 'extracted rows from a webpage',
}: ResultPreviewProps) {
  const [view, setView] = useState<View>('table');
  const setDraft = useChatStore((s) => s.setDraft);
  const draft = useChatStore((s) => s.draft);
  const setSidepanelTab = useSidepanelTabStore((s) => s.setTab);
  // Keep page hash routes and ordinary query keys while masking recognized
  // credential keys in either the query or the fragment.
  const copySource = useMemo(
    () => (source?.url ? { ...source, url: sanitizePageSourceUrl(source.url) } : (source ?? {})),
    [source],
  );

  // User-action → agent handoff (audit X3): stage the extracted rows into
  // the chat composer and jump to Chat, so user-only steps (interactive
  // picking, network capture) produce context the agent can act on.
  const sendToAgent = () => {
    const included = rows.slice(0, AGENT_HANDOFF_ROW_CAP);
    const payload = wrapJsonForAgent(included, {
      description,
      source: copySource,
      meta: {
        ...(source?.url && {
          source_kind: sourceKind === 'response' ? 'network response' : 'web page',
        }),
        row_count: rows.length,
        included_rows: included.length,
        ...(rows.length > included.length
          ? { note: 'truncated — run the saved pattern via data_patterns for the full set' }
          : {}),
      },
    });
    setDraft(draft ? `${draft}\n\n${payload}` : payload);
    setSidepanelTab('chat');
  };

  const copyOptions = useMemo(
    () => [
      {
        label: 'Copy JSON',
        description: 'Pretty-printed JSON of all rows.',
        getContent: () => stringifyJson(rows),
      },
      {
        label: 'Copy TSV',
        description: 'Tab-separated, ready to paste into a spreadsheet.',
        getContent: () => rowsToTsv(rows),
      },
      {
        label: 'Copy for AI',
        description: source?.url
          ? `JSON wrapped with ${sourceKind === 'response' ? 'response' : 'page'} URL + a one-line preamble for chat.`
          : 'JSON wrapped with a one-line preamble for chat; source URL unavailable.',
        ai: true,
        getContent: () =>
          wrapJsonForAgent(rows, {
            description,
            source: copySource,
            meta: {
              ...(source?.url && {
                source_kind: sourceKind === 'response' ? 'network response' : 'web page',
              }),
              row_count: rows.length,
            },
          }),
      },
    ],
    [rows, source?.url, sourceKind, copySource, description],
  );

  if (rows.length === 0) {
    return (
      <div className="grid place-items-center rounded-xl bg-secondary/40 px-4 py-8 text-center text-sm text-muted-foreground">
        {emptyHint ?? 'No rows extracted.'}
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <div className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
          {rows.length} row{rows.length === 1 ? '' : 's'}
        </div>
        <div className="flex items-center gap-1">
          <Button
            size="sm"
            variant="ghost"
            onClick={sendToAgent}
            title="Stage these rows in the chat composer for the agent"
            className="h-6 gap-1 rounded-md px-2 text-[10px] uppercase tracking-wider"
          >
            <Bot className="size-3" /> Send to agent
          </Button>
          <CopyMenu options={copyOptions} title="Copy" size="sm" />
          <ViewToggle active={view === 'table'} onClick={() => setView('table')}>
            <Table2 className="size-3" /> Table
          </ViewToggle>
          <ViewToggle active={view === 'json'} onClick={() => setView('json')}>
            <Braces className="size-3" /> JSON
          </ViewToggle>
        </div>
      </div>
      {view === 'table' ? (
        <TableView rows={rows} maxHeight={maxHeight} />
      ) : (
        <JsonView rows={rows} maxHeight={maxHeight} />
      )}
    </div>
  );
}

function ViewToggle({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <Button
      size="sm"
      variant="ghost"
      onClick={onClick}
      className={cn(
        'h-6 gap-1 rounded-md px-2 text-[10px] uppercase tracking-wider',
        active && 'bg-secondary text-foreground',
      )}
    >
      {children}
    </Button>
  );
}

/** JSON view stringifies up to 500 rows ONCE per rows change, not per render. */
function JsonView({ rows, maxHeight }: { rows: Record<string, unknown>[]; maxHeight: number }) {
  const JSON_VIEW_ROW_CAP = 500;
  const text = useMemo(() => {
    const capped = rows.length > JSON_VIEW_ROW_CAP;
    const body = JSON.stringify(capped ? rows.slice(0, JSON_VIEW_ROW_CAP) : rows, null, 2);
    return capped
      ? `${body}\n\n…(+${rows.length - JSON_VIEW_ROW_CAP} more rows — use Copy for all)`
      : body;
  }, [rows]);
  return (
    <pre
      className="overflow-auto whitespace-pre rounded-xl bg-secondary/40 p-3 text-[11px]"
      style={{ maxHeight }}
    >
      {text}
    </pre>
  );
}

function TableView({ rows, maxHeight }: { rows: Record<string, unknown>[]; maxHeight: number }) {
  // Column union scans every row — memoize so it runs per rows change, not
  // per render (1000 rows × 50 keys was 50k property reads a render).
  const cols = useMemo(
    () =>
      Array.from(
        rows.reduce((acc, r) => {
          for (const k of Object.keys(r)) acc.add(k);
          return acc;
        }, new Set<string>()),
      ),
    [rows],
  );

  const renderCell = (v: unknown): string => {
    if (v == null) return '';
    if (typeof v === 'string') return v;
    if (typeof v === 'number' || typeof v === 'boolean') return String(v);
    return JSON.stringify(v);
  };

  return (
    <div className="overflow-auto rounded-xl bg-secondary/40 text-[11px]" style={{ maxHeight }}>
      <table className="w-full">
        <thead className="sticky top-0 bg-secondary/90 backdrop-blur">
          <tr>
            {cols.map((c) => (
              <th
                key={c}
                className="border-b border-border/40 px-2 py-1.5 text-left font-medium text-muted-foreground"
              >
                {c}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.slice(0, 200).map((r, i) => (
            // biome-ignore lint/suspicious/noArrayIndexKey: render-only preview, rows don't reorder.
            <tr key={i} className="border-b border-border/20 last:border-0">
              {cols.map((c) => (
                <td key={c} className="max-w-[200px] truncate px-2 py-1 align-top">
                  {renderCell(r[c])}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      {rows.length > 200 && (
        <div className="px-2 py-1.5 text-center text-muted-foreground">
          Showing first 200 of {rows.length} rows — Copy and Save include all of them
        </div>
      )}
    </div>
  );
}
