    // The words reach the read door in every organization asked (`structureSearchIn`).
    async metadataSearch({ text: text2, organization_id }) {
      if (spans(organization_id) && readOrgs(organization_id).length > 0) {
        const targets = readOrgs(organization_id).filter((t) => t !== null);
        const unavailable = [];
        const answers = await Promise.all(
          targets.map(async (t) => {
            const found = await structureSearchIn(t, text2);
            if (!found.ok) {
              unavailable.push({ organization_id: t, reason: unavailableReason(found.error) });
              return { t, found };
            }
            return { t, found };
          })
        );
        const matches = [];
        const covered = [];
        let firstRefusal = null;
        for (const answer of answers) {
          if (!answer) continue;
          if (!answer.found.ok) {
            firstRefusal ??= answer.found.error;
            continue;
          }
          covered.push(answer.t);
          for (const m of answer.found.data.matches) matches.push({ ...m, organization_id: answer.t });
        }
        const inOrder = (a, b) => targets.indexOf(a.organization_id) - targets.indexOf(b.organization_id);
        unavailable.sort(inOrder);
        if (covered.length === 0 && firstRefusal) return err(firstRefusal);
        return ok({ matches, organizations_covered: covered, unavailable });
      }
      return structureSearchIn(org, text2);
    },
    async organizationsOpen(args) {
      const targets = readOrgs(args?.organization_id).filter((t) => t !== null);
      const open = [];
      const unavailable = [];
      await Promise.all(
        targets.map(async (t) => {
          const result = await clientFor(t).storeIsOpen();
          if (!result.ok) unavailable.push({ organization_id: t, reason: unavailableReason(result.error) });
          else open.push(t);
        })
      );
      const position = (id) => targets.indexOf(id);
      open.sort((a, b) => position(a) - position(b));
      unavailable.sort((a, b) => position(a.organization_id) - position(b.organization_id));
      return ok({ open, unavailable });
    },
    async ownerOrganization({ table_id, record_id, organization_id }) {
      if (table_id) {
        const read = await client.tableRead({ table_id, ...organization_id ? { organization_id } : {} });
        if (!read.ok) return err(read.error);
        return ok(read.data ? read.data.organization_id ?? null : null);
      }
      if (record_id) {
        const read = await client.recordRead({ record_id, ...organization_id ? { organization_id } : {} });
        if (!read.ok) return ok(null);
        const targets = readOrgs(organization_id);
        return ok(recordOrgs.get(record_id) ?? organization_id ?? (targets.length === 1 ? targets[0] ?? null : null));
      }
      return ok(null);
    },
    async fieldPropose() {
      const refusal = doorAbsent(DOORS.fieldPropose);
      scream({ code: refusal.code, message: refusal.message, ...refusal.hint ? { hint: refusal.hint } : {}, where: "fieldPropose" });
      return err(refusal);
    },
